// ============================================================
// Smart IV Monitoring
// Random Forest Model
//
// Trees: 30
// Maximum depth: 8
// Total nodes: 14956
//
// Features:
// 0 = Current_Bag_Weight_g
// 1 = Flow_Rate_mL_per_min
// 2 = Flow_Trend
// ============================================================


float predict_tree(
    float weight,
    float flow,
    float trend,
    const int* feature,
    const float* threshold,
    const int* left,
    const int* right,
    const float* value,
    int node_count
) {

    float inputs[3];

    inputs[0] = weight;
    inputs[1] = flow;
    inputs[2] = trend;

    int node = 0;

    while (true) {

        // Leaf node
        int left_node = pgm_read_dword(&left[node]);
        int right_node = pgm_read_dword(&right[node]);

        if (left_node == -1 && right_node == -1) {

            float leaf_value = pgm_read_float(&value[node]);

            return leaf_value;
        }

        int feature_index =
            pgm_read_dword(&feature[node]);

        float split_threshold =
            pgm_read_float(&threshold[node]);

        if (inputs[feature_index] <= split_threshold) {
            node = left_node;
        }
        else {
            node = right_node;
        }
    }
}

